use vstd::prelude::*;

verus! {
    fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
        requires
            // The input vector can be of any length, including zero.
            true,
        ensures
            // The result vector has the same length as the input vector.
            result.len() == m.len() &&
            // For every valid index i, the element at index i of the result
            // is equal to the element at index (n - 1 - i) of the input.
            forall|i: nat| (i < m.len() as nat) ==> result[i] == m[(m.len() as nat - 1 - i)],
    {
        let n = m.len() as nat;
        let mut result: Vec<f32> = vec![0.0; n as usize]; // Initialize result vector with the same length

        let mut i: nat = 0; // Index for the result vector
        while i < n
            invariant
                i <= n,
                result.len() == m.len(),
                forall|j: nat| (j < i) ==> result[j] == m[(n - 1 - j)],
            decreases n - i,
        {
            result[i as usize] = m[(n - 1 - i) as usize]; // Fill result in reverse order
            i = i + 1; // Move to the next index
        }
        result
    }
}

